Find every security problem in this login handler:

```js
app.post('/login', async (req, res) => {
  const { email, password } = req.body;
  const user = await db.findUserByEmail(email);
  if (!user) return res.status(401).send('No account with that email');
  const hash = crypto.createHash('sha256').update(password).digest('hex');
  if (hash !== user.passwordHash) return res.status(401).send('Wrong password');
  res.cookie('session', JSON.stringify({ userId: user.id, role: user.role }));
  res.send('ok');
});
```

