```js
app.post('/login', loginRateLimiter, async (req, res) => {
  const { email, password } = req.body;
  const user = await db.findUserByEmail(email);
  // verify against a dummy hash when the user is missing, to keep timing similar
  const ok = await argon2.verify(user?.passwordHash ?? DUMMY_HASH, password); // salted, slow
  if (!user || !ok) return res.status(401).send('Invalid email or password');
  const sid = crypto.randomBytes(32).toString('hex');
  await sessions.set(sid, { userId: user.id }, { ttlSeconds: 86400 }); // role looked up server-side
  res.cookie('sid', sid, { httpOnly: true, secure: true, sameSite: 'lax', maxAge: 86400000 });
  res.send('ok');
});
```
